import {MotionRecorder} from '../animation/record-motion.js';
export function refreshRecordMotion(a){if(a.motionRecorder?.active)a.timeline?.refreshMotionRanges?.();const button=document.querySelector('#record-motion'),status=document.querySelector('#motion-record-status');if(!button)return;button.classList.toggle('active',!!a.recordMotionArmed);button.classList.toggle('capturing',!!a.motionRecorder?.active);button.setAttribute('aria-pressed',String(!!a.recordMotionArmed));button.textContent=a.motionRecorder?.active?'● Recording…':'● Record motion';const text=a.motionRecorder?.active?a.motionRecordStatus:a.recordMotionArmed?(a.tool!=='select'?'Use Select to record motion':a.motionRecordStatus||'Drag artwork to record'):'';status.textContent=text;status.hidden=!text;status.title=text;const auto=document.querySelector('#auto-key');if(auto){auto.setAttribute('aria-pressed',String(!!a.autoKey));auto.classList.toggle('active',!!a.autoKey);}}
export function cancelRecordMotionForKey(a,e){if(!a.motionRecorder?.active||e.target?.closest?.('input,textarea,select'))return false;const command=e.metaKey||e.ctrlKey,key=e.key?.toLowerCase();if(e.key==='Escape'||command&&['z','s','d','x','c','v'].includes(key)||e.code==='Space'||['Delete','Backspace','Enter'].includes(e.key)||!command&&['v','a','m','r','e','p','b','t','h'].includes(key)){a.motionRecorder.cancel({render:false});return true;}return false;}
export function bindRecordMotion(a){if(document.querySelector('#record-motion'))return;a.recordMotionArmed=false;a.motionRecorder=new MotionRecorder(a);const button=document.createElement('button');button.id='record-motion';button.type='button';button.setAttribute('aria-pressed','false');button.title='Arm motion recording, then drag artwork with Select. Each drag is one take.';const status=document.createElement('output');status.id='motion-record-status';status.hidden=true;const actions=document.querySelector('.stage-actions');actions.insertBefore(button,actions.firstChild);button.after(status);button.onclick=()=>{if(a.motionRecorder.active)a.motionRecorder.cancel();a.properties.flush();a.stage.finishPath();a.pause();a.recordMotionArmed=!a.recordMotionArmed;a.motionRecordStatus=a.recordMotionArmed?'Drag artwork to record':'';if(a.recordMotionArmed){a.tool='select';a.nodeEdit=false;a.pivotEdit=false;a.meshPlacement=null;a.meshInsert=false;a.meshSplit=false;}a.render();};document.addEventListener('keydown',e=>cancelRecordMotionForKey(a,e),true);document.addEventListener('pointerdown',e=>{if(a.motionRecorder.active&&!a.stage.el.contains(e.target))a.motionRecorder.cancel();},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)a.motionRecorder.cancel();});window.addEventListener('blur',()=>a.motionRecorder.cancel());refreshRecordMotion(a);}
